record.field:
ga = document.worksheet_id.general_audit_id
months = 0
if ga.date_start and ga.date_end:
    months = (
        (ga.date_end.year - ga.date_start.year) * 12
        + (ga.date_end.month - ga.date_start.month)
        + 1
    )
if months == 12:
    result = "Yearly Financial Report"
elif months and months < 12:
    result = "Interim Financial Report"
elif months > 12:
    result = "More than 12 months"
else:
    result = ""

result = 0.0
lines = document.worksheet_id.general_audit_id.computation_ids.filtered(
    lambda c: c.computation_item_id.name == "Total Revenue"
)
if lines:
    result = lines[0].audited_amount

